import{_ as i,W as o,s as l,u as c,ah as d,I as t,w as s,Z as e,A as p}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const C=JSON.parse('{"title":"查看远程 Linux 系统中某个端口是否开启的 3 种方法 | LCTT x X-CMD","titleTemplate":false,"description":"查看远程 Linux 系统中某个端口是否开启的 3 种方法 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"查看远程 Linux 系统中某个端口是否开启的 3 种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"查看远程 Linux 系统中某个端口是否开启的 3 种方法 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190318 3 Ways To Check Whether A Port Is Open On The Remote Linux System","title":"查看远程 Linux 系统中某个端口是否开启的 3 种方法","tag":"201904"},"relativePath":"201904/20190318 3 Ways To Check Whether A Port Is Open On The Remote Linux System.md","filePath":"[post].md"}'),r={name:"201904/20190318 3 Ways To Check Whether A Port Is Open On The Remote Linux System.md"};function u(h,n,m,g,b,x){const a=o("Link");return c(),l("div",null,[n[15]||(n[15]=d(`<h1 id="查看远程-linux-系统中某个端口是否开启的-3-种方法" tabindex="-1">查看远程 Linux 系统中某个端口是否开启的 3 种方法 <a class="header-anchor" href="#查看远程-linux-系统中某个端口是否开启的-3-种方法" aria-label="Permalink to 查看远程 Linux 系统中某个端口是否开启的 3 种方法">​</a></h1><p>这是一个很重要的话题，不仅对 Linux 管理员而言，对于我们大家而言也非常有帮助。我的意思是说对于工作在 IT 基础设施行业的用户来说，了解这个话题也是非常有用的。他们需要在执行下一步操作前，检查 Linux 服务器上某个端口是否开启。</p><p>假如这个端口没有被开启，则他们会直接找 Linux 管理员去开启它。如果这个端口已经开启了，则我们需要和应用团队来商量下一步要做的事。</p><p>在本篇文章中，我们将向你展示如何检查某个端口是否开启的 3 种方法。</p><p>这个目标可以使用下面的 Linux 命令来达成：</p><ul><li><code>nc</code>：netcat 是一个简单的 Unix 工具，它使用 TCP 或 UDP 协议去读写网络连接间的数据。</li><li><code>nmap</code>：（“Network Mapper”）是一个用于网络探索和安全审计的开源工具，被设计用来快速地扫描大规模网络。</li><li><code>telnet</code>：被用来交互地通过 TELNET 协议与另一台主机通信。</li></ul><h3 id="如何使用-nc-netcat-命令来查看远程-linux-系统中某个端口是否开启" tabindex="-1">如何使用 nc（netcat）命令来查看远程 Linux 系统中某个端口是否开启？ <a class="header-anchor" href="#如何使用-nc-netcat-命令来查看远程-linux-系统中某个端口是否开启" aria-label="Permalink to 如何使用 nc（netcat）命令来查看远程 Linux 系统中某个端口是否开启？">​</a></h3><p><code>nc</code> 即 <code>netcat</code>。<code>netcat</code> 是一个简单的 Unix 工具，它使用 TCP 或 UDP 协议去读写网络连接间的数据。</p><p>它被设计成为一个可信赖的后端工具，可被直接使用或者简单地被其他程序或脚本调用。</p><p>与此同时，它也是一个富含功能的网络调试和探索工具，因为它可以创建你所需的几乎所有类型的连接，并且还拥有几个内置的有趣功能。</p><p><code>netcat</code> 有三类功能模式，它们分别为连接模式、监听模式和隧道模式。</p><p><code>nc</code>（<code>netcat</code>）命令的一般语法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ nc [-options] [HostName or IP] [PortNumber]</span></span></code></pre></div><p>在下面的例子中，我们将检查远程 Linux 系统中的 22 端口是否开启。</p><p>假如端口是开启的，你将获得类似下面的输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># nc -zvw3 192.168.1.8 22</span></span>
<span class="line"><span>Connection to 192.168.1.8 22 port [tcp/ssh] succeeded!</span></span></code></pre></div><p>命令详解：</p><ul><li><code>nc</code>：即执行的命令主体；</li><li><code>z</code>：零 I/O 模式（被用来扫描）；</li><li><code>v</code>：显式地输出；</li><li><code>w3</code>：设置超时时间为 3 秒；</li><li><code>192.168.1.8</code>：目标系统的 IP 地址；</li><li><code>22</code>：需要验证的端口。</li></ul><p>当检测到端口没有开启，你将获得如下输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># nc -zvw3 192.168.1.95 22</span></span>
<span class="line"><span>nc: connect to 192.168.1.95 port 22 (tcp) failed: Connection refused</span></span></code></pre></div><h3 id="如何使用-nmap-命令来查看远程-linux-系统中某个端口是否开启" tabindex="-1">如何使用 nmap 命令来查看远程 Linux 系统中某个端口是否开启？ <a class="header-anchor" href="#如何使用-nmap-命令来查看远程-linux-系统中某个端口是否开启" aria-label="Permalink to 如何使用 nmap 命令来查看远程 Linux 系统中某个端口是否开启？">​</a></h3><p><code>nmap</code>（“Network Mapper”）是一个用于网络探索和安全审计的开源工具，被设计用来快速地扫描大规模网络，尽管对于单个主机它也同样能够正常工作。</p><p><code>nmap</code> 以一种新颖的方式，使用裸 IP 包来决定网络中的主机是否可达，这些主机正提供什么服务（应用名和版本号），它们运行的操作系统（系统的版本），它们正在使用的是什么包过滤软件或者防火墙，以及其他额外的特性。</p><p>尽管 <code>nmap</code> 通常被用于安全审计，许多系统和网络管理员发现在一些日常任务（例如罗列网络资产、管理服务升级的计划、监视主机或者服务是否正常运行）中，它也同样十分有用。</p><p><code>nmap</code> 的一般语法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ nmap [-options] [HostName or IP] [-p] [PortNumber]</span></span></code></pre></div><p>假如端口是开启的，你将获得如下的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># nmap 192.168.1.8 -p 22</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Starting Nmap 7.70 ( https://nmap.org ) at 2019-03-16 03:37 IST Nmap scan report for 192.168.1.8 Host is up (0.00031s latency).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PORT STATE SERVICE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>22/tcp open ssh </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Nmap done: 1 IP address (1 host up) scanned in 13.06 seconds</span></span></code></pre></div><p>假如端口没有开启，你将得到类似下面的结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># nmap 192.168.1.8 -p 80</span></span>
<span class="line"><span>Starting Nmap 7.70 ( https://nmap.org ) at 2019-03-16 04:30 IST</span></span>
<span class="line"><span>Nmap scan report for 192.168.1.8</span></span>
<span class="line"><span>Host is up (0.00036s latency).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PORT   STATE  SERVICE</span></span>
<span class="line"><span>80/tcp closed http</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Nmap done: 1 IP address (1 host up) scanned in 13.07 seconds</span></span></code></pre></div><h3 id="如何使用-telnet-命令来查看远程-linux-系统中某个端口是否开启" tabindex="-1">如何使用 telnet 命令来查看远程 Linux 系统中某个端口是否开启？ <a class="header-anchor" href="#如何使用-telnet-命令来查看远程-linux-系统中某个端口是否开启" aria-label="Permalink to 如何使用 telnet 命令来查看远程 Linux 系统中某个端口是否开启？">​</a></h3><p><code>telnet</code> 命令被用来交互地通过 TELNET 协议与另一台主机通信。</p><p><code>telnet</code> 命令的一般语法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ telnet [HostName or IP] [PortNumber]</span></span></code></pre></div><p>假如探测成功，你将看到类似下面的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ telnet 192.168.1.9 22</span></span>
<span class="line"><span>Trying 192.168.1.9...</span></span>
<span class="line"><span>Connected to 192.168.1.9.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>SSH-2.0-OpenSSH_5.3</span></span>
<span class="line"><span>^]</span></span>
<span class="line"><span>Connection closed by foreign host.</span></span></code></pre></div><p>假如探测失败，你将看到类似下面的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ telnet 192.168.1.9 80</span></span>
<span class="line"><span>Trying 192.168.1.9...</span></span>
<span class="line"><span>telnet: Unable to connect to remote host: Connection refused</span></span></code></pre></div><p>当前，我们只找到上面 3 种方法来查看远程 Linux 系统中某个端口是否开启，假如你发现了其他方法可以达到相同的目的，请在下面的评论框中告知我们。</p><hr>`,40)),t("p",null,[n[1]||(n[1]=s("via: ")),e(a,{href:"https://www.2daygeek.com/how-to-check-whether-a-port-is-open-on-the-remote-linux-system-server/"},{default:p(()=>n[0]||(n[0]=[s("https://www.2daygeek.com/how-to-check-whether-a-port-is-open-on-the-remote-linux-system-server/")])),_:1})]),t("p",null,[n[6]||(n[6]=s("作者：")),e(a,{href:"https://www.2daygeek.com/author/magesh/"},{default:p(()=>n[2]||(n[2]=[s("Magesh Maruthamuthu")])),_:1}),n[7]||(n[7]=s(" 选题：")),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>n[3]||(n[3]=[s("lujun9972")])),_:1}),n[8]||(n[8]=s(" 译者：")),e(a,{href:"https://github.com/FSSlc"},{default:p(()=>n[4]||(n[4]=[s("FSSlc")])),_:1}),n[9]||(n[9]=s(" 校对：")),e(a,{href:"https://github.com/wxy"},{default:p(()=>n[5]||(n[5]=[s("wxy")])),_:1})]),t("p",null,[n[12]||(n[12]=s("本文由 ")),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>n[10]||(n[10]=[s("LCTT")])),_:1}),n[13]||(n[13]=s(" 原创编译，")),e(a,{href:"https://linux.cn/"},{default:p(()=>n[11]||(n[11]=[s("Linux中国")])),_:1}),n[14]||(n[14]=s(" 荣誉推出"))])])}const k=i(r,[["render",u]]);export{C as __pageData,k as default};
